* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
}

.calculator {
    background: #fff;
    border-radius: 20px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
    overflow: hidden;
    width: 320px;
}

.display {
    background: #222;
    color: #fff;
    padding: 30px 20px;
    text-align: right;
    min-height: 100px;
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
}

.previous-operand {
    color: rgba(255, 255, 255, 0.6);
    font-size: 18px;
    min-height: 25px;
    word-wrap: break-word;
    word-break: break-all;
}

.current-operand {
    color: #fff;
    font-size: 32px;
    font-weight: bold;
    min-height: 40px;
    word-wrap: break-word;
    word-break: break-all;
}

.buttons {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1px;
    background: #e0e0e0;
    padding: 1px;
}

button {
    border: none;
    background: #f9f9f9;
    font-size: 20px;
    padding: 25px;
    cursor: pointer;
    transition: all 0.2s;
    font-weight: 500;
}

button:hover {
    background: #e8e8e8;
}

button:active {
    transform: scale(0.95);
}

.span-two {
    grid-column: span 2;
}

.operator {
    background: #ff9500;
    color: #fff;
}

.operator:hover {
    background: #e68600;
}

.clear {
    background: #d4d4d2;
    color: #000;
}

.clear:hover {
    background: #c0c0be;
}

.delete {
    background: #d4d4d2;
    color: #000;
}

.delete:hover {
    background: #c0c0be;
}

.equals {
    background: #34c759;
    color: #fff;
}

.equals:hover {
    background: #2db34a;
}

.number {
    color: #333;
}

.decimal {
    color: #333;
}

@media (max-width: 400px) {
    .calculator {
        width: 100%;
        border-radius: 0;
    }
}

class Calculator {
    constructor() {
        this.currentValue = '0';
        this.previousValue = '';
        this.operation = null;
        this.shouldResetDisplay = false;
    }

    clear() {
        this.currentValue = '0';
        this.previousValue = '';
        this.operation = null;
        this.shouldResetDisplay = false;
    }

    delete() {
        if (this.currentValue.length === 1) {
            this.currentValue = '0';
        } else {
            this.currentValue = this.currentValue.slice(0, -1);
        }
    }

    appendNumber(number) {
        if (this.shouldResetDisplay) {
            this.currentValue = number;
            this.shouldResetDisplay = false;
            return;
        }

        if (number === '.' && this.currentValue.includes('.')) return;

        if (this.currentValue === '0' && number !== '.') {
            this.currentValue = number;
        } else {
            this.currentValue += number;
        }
    }

    chooseOperation(operation) {
        if (this.currentValue === '') return;

        if (this.previousValue !== '') {
            this.calculate();
        }

        this.operation = operation;
        this.previousValue = this.currentValue;
        this.shouldResetDisplay = true;
    }

    calculate() {
        let result;
        const prev = parseFloat(this.previousValue);
        const current = parseFloat(this.currentValue);

        if (isNaN(prev) || isNaN(current)) return;

        switch (this.operation) {
            case '+':
                result = prev + current;
                break;
            case '-':
                result = prev - current;
                break;
            case '×':
                result = prev * current;
                break;
            case '÷':
                if (current === 0) {
                    alert('Cannot divide by zero!');
                    this.clear();
                    return;
                }
                result = prev / current;
                break;
            case '%':
                result = prev % current;
                break;
            default:
                return;
        }

        // Round to avoid floating point errors
        result = Math.round(result * 100000000) / 100000000;

        this.currentValue = result.toString();
        this.operation = null;
        this.previousValue = '';
        this.shouldResetDisplay = true;
    }

    getDisplayValue() {
        return this.currentValue;
    }

    getOperationDisplay() {
        if (this.operation && this.previousValue) {
            return `${this.previousValue} ${this.operation}`;
        }
        return '';
    }
}

// Initialize calculator
const calculator = new Calculator();
const display = document.getElementById('display');
const operationDisplay = document.getElementById('operation-display');

function updateDisplay() {
    display.textContent = calculator.getDisplayValue();
    operationDisplay.textContent = calculator.getOperationDisplay();
}

// Number buttons
document.querySelectorAll('[data-number]').forEach(button => {
    button.addEventListener('click', () => {
        calculator.appendNumber(button.textContent);
        updateDisplay();
    });
});

// Operation buttons
document.querySelectorAll('[data-operation]').forEach(button => {
    button.addEventListener('click', () => {
        calculator.chooseOperation(button.textContent);
        updateDisplay();
    });
});

// Equals button
document.getElementById('equals').addEventListener('click', () => {
    calculator.calculate();
    updateDisplay();
});

// Clear button
document.getElementById('clear').addEventListener('click', () => {
    calculator.clear();
    updateDisplay();
});

// Delete button
document.getElementById('delete').addEventListener('click', () => {
    calculator.delete();
    updateDisplay();
});

// Keyboard support
document.addEventListener('keydown', (e) => {
    if (e.key >= '0' && e.key <= '9' || e.key === '.') {
        calculator.appendNumber(e.key);
        updateDisplay();
    }

    if (e.key === '+' || e.key === '-' || e.key === '*' || e.key === '/' || e.key === '%') {
        const operationMap = {
            '*': '×',
            '/': '÷',
            '+': '+',
            '-': '-',
            '%': '%'
        };
        calculator.chooseOperation(operationMap[e.key]);
        updateDisplay();
    }

    if (e.key === 'Enter' || e.key === '=') {
        e.preventDefault();
        calculator.calculate();
        updateDisplay();
    }

    if (e.key === 'Escape') {
        calculator.clear();
        updateDisplay();
    }

    if (e.key === 'Backspace') {
        e.preventDefault();
        calculator.delete();
        updateDisplay();
    }
});

// Initialize display
updateDisplay();

