    if (e.key >= '0' && e.key <= '9' || e.key === '.') {
        calculator.appendNumber(e.key);
        updateDisplay();
    }

    if (e.key === '+' || e.key === '-' || e.key === '*' || e.key === '/' || e.key === '%') {
        const operationMap = {
            '*': '×',
            '/': '÷',
            '+': '+',
            '-': '-',
            '%': '%'
        };
        calculator.chooseOperation(operationMap[e.key]);
        updateDisplay();
    }

    if (e.key === 'Enter' || e.key === '=') {
        e.preventDefault();
        calculator.calculate();
        updateDisplay();
    }

    if (e.key === 'Escape') {
        calculator.clear();
        updateDisplay();
    }

    if (e.key === 'Backspace') {
        e.preventDefault();
        calculator.delete();
        updateDisplay();
    }
});

// Initialize display
updateDisplay();

